DROP TABLE IF EXISTS `field_definitions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `field_definitions` (
  `id` int NOT NULL AUTO_INCREMENT,
  `entity` varchar(100) NOT NULL,
  `key` varchar(100) NOT NULL,
  `label` varchar(255) NOT NULL,
  `type` varchar(50) NOT NULL DEFAULT 'text',
  `number_format` varchar(20) DEFAULT NULL COMMENT 'integer|float|currency',
  `decimal_places` int DEFAULT NULL COMMENT 'So chu so thap phan',
  `display_format` varchar(20) DEFAULT 'plain',
  `unit` varchar(50) DEFAULT NULL,
  `date_format` varchar(30) DEFAULT NULL COMMENT 'DD/MM/YYYY, YYYY-MM-DD, etc.',
  `timezone` varchar(50) DEFAULT NULL COMMENT 'Mui gio',
  `source_type` varchar(20) NOT NULL DEFAULT 'json',
  `required` tinyint(1) NOT NULL DEFAULT '0',
  `validation` json DEFAULT NULL,
  `options` json DEFAULT NULL,
  `data_list_id` int DEFAULT NULL COMMENT 'Tham chiáº¿u data_lists.id. NULL=options thá»§ cÃ´ng',
  `data_list_column` varchar(100) DEFAULT NULL COMMENT 'Column key trong data list',
  `data_list_label_column` varchar(100) DEFAULT NULL,
  `relation_key` varchar(100) DEFAULT NULL COMMENT 'Column key trong data list chá»©a FK vá» parent field value',
  `auto_fill` tinyint(1) DEFAULT '0' COMMENT 'Auto-fill khi parent thay Ä‘á»•i vÃ  chá»‰ cÃ³ 1 giÃ¡ trá»‹',
  `source_config` json DEFAULT NULL COMMENT 'Cau hinh data source cho select',
  `parent_field` varchar(100) DEFAULT NULL COMMENT 'Field key cá»§a parent cho cascading',
  `option_style` json DEFAULT NULL COMMENT 'Style cho options: color, borderRadius',
  `file_config` json DEFAULT NULL COMMENT 'Cau hinh file: accept, maxSize, multiple',
  `formula_config` json DEFAULT NULL COMMENT 'Cau hinh formula: expression, referencedFields',
  `formula` varchar(500) DEFAULT NULL,
  `placeholder` varchar(255) DEFAULT NULL,
  `help_text` varchar(500) DEFAULT NULL,
  `status` enum('active','inactive') NOT NULL DEFAULT 'active',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_entity_key` (`entity`,`key`),
  KEY `idx_entity` (`entity`),
  KEY `idx_status` (`status`),
  KEY `data_list_id` (`data_list_id`),
  CONSTRAINT `field_definitions_ibfk_1` FOREIGN KEY (`data_list_id`) REFERENCES `data_lists` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=160 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
